TOPICS = [
 dict(title='Repair cafes',
 text='A repair cafe brings volunteers and residents together to fix household objects. Its purpose is not simply to save the price of a replacement. By explaining each step, volunteers help owners understand why an object failed and how to maintain it. Some visitors arrive expecting a free repair service, however, and feel disappointed when they must participate. Organisers therefore describe the learning element clearly before accepting bookings. They also record items that cannot be repaired. These records can reveal recurring design problems, although they cannot establish how common a fault is across all products sold. A cafe sees only the objects that people choose to bring. Manufacturers could still use this limited evidence to identify components worth investigating. The strongest argument for a cafe is consequently educational rather than statistical: a successful visit can change the way someone thinks about ownership, even when the object itself remains broken.',
 gaps=[('purpose','profit','surface','distance'), ('participate','disappear','compete','purchase'), ('recurring','temporary','imaginary','unrelated')],
 summary='Repair cafes teach owners maintenance skills through participation, while records of failed repairs can suggest design issues but cannot establish their prevalence because visitors bring a self-selected sample of products.',
 main='Their educational value extends beyond whether each item is repaired.',
 wrong=['They provide representative statistics on all household products.', 'Their main purpose is to replace professional repair businesses.', 'They require manufacturers to redesign every faulty component.'],
 facts=['Owners are expected to participate in the repair process.', 'Repair records may help identify components for further investigation.'],
 false=['Every object brought to a cafe is successfully repaired.', 'Cafe visitors form a random sample of product owners.'],
 keywords=['repair', 'owners', 'learning', 'records', 'sample'],
 ending='The object may remain broken, but the visitor can still leave with greater', missing='understanding',
 dictation='The workshop accepts bookings through the community centre website.',
 short='What do we call a person who offers their time without payment?', answer='A volunteer',
 extra='Consider a visitor with a desk lamp. A volunteer may find that a replacement switch is no longer available. The visit has not restored the lamp, but the owner has learned why access to spare parts matters. That knowledge may influence a later purchase. Another visitor may decide to clean an appliance regularly after seeing how dust affected its performance. Neither outcome appears in a count of completed repairs. Organisers should therefore ask what participants learned, as well as whether their objects function again. Enthusiasm should not replace safety: volunteers need clear limits on their work and should refer unsuitable jobs to qualified professionals.'),
]
